mapper.insert:
INSERT INTO WORKOUT_RECORD (
    WORKOUT_RECORD_ID /* 운동기록아이디 */
  , USER_ID           /* 회원아이디 */
  , CATEGORY_CD       /* 카테고리코드 */
  , RECORD_DT         /* 기록일시 */
  , DURATION_MIN      /* 운동시간(분) */
  , REG_DT            /* 등록일시 */
  , MOD_DT            /* 변경일시 */
) VALUES (
    #{workoutRecordId, jdbcType=NUMERIC}
  , #{userId, jdbcType=NUMERIC}
  , #{dto.categoryCd}
  , #{dto.recordDt}
  , NVL(#{dto.durationMin, jdbcType=NUMERIC}, 0)
  , SYSDATE
  , SYSDATE
)

INSERT INTO WORKOUT_RECORD_EXERCISE (
    WORKOUT_RECORD_EXERCISE_ID /* 상세기록아이디 */
  , WORKOUT_RECORD_ID          /* 운동기록아이디 */
  , EXERCISE_ID                /* 운동아이디 */
  , SORT_NO                    /* 정렬순서 */
) VALUES (
    #{workoutRecordExerciseId, jdbcType=NUMERIC}
  , #{workoutRecordId, jdbcType=NUMERIC}
  , #{dto.exerciseId, jdbcType=NUMERIC}
  , NVL(#{dto.sortNo, jdbcType=NUMERIC}, 0)
)

INSERT INTO WORKOUT_RECORD_SET (
    WORKOUT_RECORD_SET_ID      /* 세트기록아이디 */
  , WORKOUT_RECORD_EXERCISE_ID /* 상세기록아이디 */
  , SET_NO                     /* 세트번호 */
  , WEIGHT                     /* 중량 */
  , REPS                       /* 횟수 */
) VALUES (
    #{workoutRecordSetId, jdbcType=NUMERIC}
  , #{workoutRecordExerciseId, jdbcType=NUMERIC}
  , #{dto.setNo, jdbcType=NUMERIC}
  , NVL(#{dto.weight, jdbcType=NUMERIC}, 0)
  , NVL(#{dto.reps, jdbcType=NUMERIC}, 0)
)

mapper.update:
UPDATE WORKOUT_RECORD
SET CATEGORY_CD = #{dto.categoryCd}
  , RECORD_DT = #{dto.recordDt}
  , DURATION_MIN = NVL(#{dto.durationMin, jdbcType=NUMERIC}, 0)
  , MOD_DT = SYSDATE
WHERE WORKOUT_RECORD_ID = #{workoutRecordId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM WORKOUT_RECORD
WHERE WORKOUT_RECORD_ID = #{workoutRecordId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}
